WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.Score, p.ViewCount, p.CreationDate, ROW_NUMBER() OVER (PARTITION BY p.PostTypeId ORDER BY p.Score DESC NULLS FIRST) AS RankByScore, RANK() OVER (PARTITION BY p.PostTypeId ORDER BY p.ViewCount DESC NULLS FIRST) AS RankByViews FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), UserBadges AS (SELECT u.Id AS UserId, COUNT(b.Id) AS BadgeCount FROM Users AS u LEFT JOIN Badges AS b ON u.Id = b.UserId GROUP BY u.Id), PostCloseReasons AS (SELECT ph.PostId, COUNT(ph.Id) AS CloseCount, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId IN (10, 11) GROUP BY ph.PostId) SELECT rp.PostId, rp.Title, rp.Score, rp.ViewCount, rp.CreationDate, rb.BadgeCount, pc.CloseCount, pc.CloseReasons FROM RankedPosts AS rp LEFT JOIN UserBadges AS rb ON rp.PostId = rb.UserId LEFT JOIN PostCloseReasons AS pc ON rp.PostId = pc.PostId WHERE rp.RankByScore <= 10 OR rp.RankByViews <= 10 ORDER BY rp.Score DESC NULLS FIRST, rp.ViewCount DESC NULLS FIRST